<?php
$approvedReviews = $conn->query("SELECT r.rating, r.review_text, u.full_name FROM reviews r JOIN users u ON u.id = r.user_id WHERE r.status = 'Approved' ORDER BY r.created_at DESC LIMIT 3")->fetchAll();
?>
<?php if ($approvedReviews): ?><section class="py-5"><div class="container"><div class="text-center mb-4"><span class="section-tag">Kind words</span><h2 class="section-title">What Guests Say</h2></div><div class="row g-4"><?php foreach ($approvedReviews as $review): ?><div class="col-md-4"><figure class="card h-100 border-0 shadow-sm rounded-4"><blockquote class="card-body mb-0"><div class="text-warning mb-2" aria-label="<?= (int) $review['rating'] ?> out of 5 stars"><?php for ($i = 1; $i <= (int) $review['rating']; $i++): ?><i class="fa-solid fa-star" aria-hidden="true"></i><?php endfor; ?></div><p>“<?= e($review['review_text']) ?>”</p><figcaption class="fw-semibold"><?= e($review['full_name']) ?></figcaption></blockquote></figure></div><?php endforeach; ?></div></div></section><?php endif; ?>
